//! Server configurations: client authentication, ALPN, versions and a key that never leaves its
//! owner. Every certificate is generated by the test.

mod support;

use std::sync::Arc;
use std::sync::atomic::{AtomicUsize, Ordering};

use coqui_sslcontext::{
    ClientAuth, ClientCertificates, Error, Identity, KeyLogging, ServerTls, Tls, TlsVersion, Trust,
};
use rustls::SignatureScheme;
use rustls::sign::{Signer, SigningKey};
use support::pki::{Ca, Leaf};
use support::tls_server::{TlsServer, https_exchange, https_get};

fn identity(leaf: &Leaf) -> Identity {
    let key = rustls::crypto::ring::sign::any_supported_type(&leaf.key()).unwrap();
    Identity::new(leaf.chain.clone(), key, "test").unwrap()
}

fn client(ca: &Ca, certificate: Option<&Leaf>) -> Tls {
    let builder = Tls::builder().trust(Trust::Roots(vec![ca.der()]));
    match certificate {
        Some(leaf) => builder
            .client_certificates(ClientCertificates::Identity(identity(leaf)))
            .build()
            .unwrap(),
        None => builder
            .client_certificates(ClientCertificates::None)
            .build()
            .unwrap(),
    }
}

fn serve(tls: &ServerTls) -> TlsServer {
    TlsServer::start_config(tls.server_config())
}

#[test]
fn a_server_without_client_authentication_serves_any_client() {
    let ca = Ca::new("Server CA");
    let server_tls = ServerTls::builder(identity(&ca.issue_server("localhost")))
        .build()
        .unwrap();
    let server = serve(&server_tls);
    let reply = https_get(
        client(&ca, None).client_config("localhost").unwrap(),
        server.addr,
        "localhost",
    )
    .unwrap();
    assert!(reply.ends_with("no client certificate"));
}

#[test]
fn required_client_certificates_are_verified_against_the_named_trust() {
    let ca = Ca::new("Server CA");
    let client_ca = Ca::new("Client CA");
    let other_ca = Ca::new("Other Client CA");
    let server_tls = ServerTls::builder(identity(&ca.issue_server("localhost")))
        .client_auth(ClientAuth::Required(Trust::Roots(vec![client_ca.der()])))
        .build()
        .unwrap();
    let server = serve(&server_tls);
    let get = |leaf: Option<&Leaf>| {
        https_get(
            client(&ca, leaf).client_config("localhost").unwrap(),
            server.addr,
            "localhost",
        )
    };

    let good = client_ca.issue_client("good-user");
    assert!(
        get(Some(&good))
            .unwrap()
            .ends_with("client certificate seen")
    );
    assert_eq!(server.presented()[0].as_deref(), Some(good.leaf_der()));
    assert!(get(None).is_err(), "a client with none is refused");
    assert!(
        get(Some(&other_ca.issue_client("stranger"))).is_err(),
        "a client from another CA is refused"
    );
}

#[test]
fn optional_client_certificates_let_none_through_but_still_verify_one_sent() {
    let ca = Ca::new("Server CA");
    let client_ca = Ca::new("Client CA");
    let other_ca = Ca::new("Other Client CA");
    let server_tls = ServerTls::builder(identity(&ca.issue_server("localhost")))
        .client_auth(ClientAuth::Optional(Trust::Roots(vec![client_ca.der()])))
        .build()
        .unwrap();
    let server = serve(&server_tls);
    let get = |leaf: Option<&Leaf>| {
        https_get(
            client(&ca, leaf).client_config("localhost").unwrap(),
            server.addr,
            "localhost",
        )
    };
    assert!(get(None).unwrap().ends_with("no client certificate"));
    assert!(
        get(Some(&client_ca.issue_client("ok")))
            .unwrap()
            .ends_with("client certificate seen")
    );
    assert!(get(Some(&other_ca.issue_client("bad"))).is_err());
}

#[test]
fn the_client_trust_may_be_a_bundle_file() {
    let ca = Ca::new("Server CA");
    let client_ca = Ca::new("Client CA");
    let directory = tempfile::tempdir().unwrap();
    let bundle = directory.path().join("clients.pem");
    std::fs::write(
        &bundle,
        support::pem::pem("CERTIFICATE", client_ca.der().as_ref()),
    )
    .unwrap();
    let server_tls = ServerTls::builder(identity(&ca.issue_server("localhost")))
        .client_auth(ClientAuth::Required(Trust::Bundle(bundle)))
        .build()
        .unwrap();
    let server = serve(&server_tls);
    let leaf = client_ca.issue_client("bundle-user");
    https_get(
        client(&ca, Some(&leaf)).client_config("localhost").unwrap(),
        server.addr,
        "localhost",
    )
    .unwrap();
}

#[test]
fn a_client_trust_that_verifies_nothing_is_refused_at_build_time() {
    let ca = Ca::new("Server CA");
    let leaf = identity(&ca.issue_server("localhost"));
    for auth in [
        ClientAuth::Required(Trust::Disabled),
        ClientAuth::Optional(Trust::Disabled),
        ClientAuth::Required(Trust::Roots(Vec::new())),
    ] {
        let built = ServerTls::builder(leaf.clone()).client_auth(auth).build();
        assert!(matches!(built, Err(Error::Tls(_))));
    }
}

#[test]
fn alpn_and_versions_are_negotiated_within_the_configured_bounds() {
    let ca = Ca::new("Server CA");
    let leaf = ca.issue_server("localhost");
    let server_tls = ServerTls::builder(identity(&leaf))
        .alpn(["http/1.1"])
        .build()
        .unwrap();
    let server = serve(&server_tls);
    let client_tls = Tls::builder()
        .trust(Trust::Roots(vec![ca.der()]))
        .client_certificates(ClientCertificates::None)
        .alpn(["h2", "http/1.1"])
        .build()
        .unwrap();
    let exchange = https_exchange(
        client_tls.client_config("localhost").unwrap(),
        server.addr,
        "localhost",
    )
    .unwrap();
    assert_eq!(exchange.alpn.as_deref(), Some(&b"http/1.1"[..]));
    assert_eq!(exchange.version, Some(rustls::ProtocolVersion::TLSv1_3));

    let only12 = ServerTls::builder(identity(&leaf))
        .maximum_version(TlsVersion::Tls12)
        .build()
        .unwrap();
    let server12 = serve(&only12);
    let exchange = https_exchange(
        client_tls.client_config("localhost").unwrap(),
        server12.addr,
        "localhost",
    )
    .unwrap();
    assert_eq!(exchange.version, Some(rustls::ProtocolVersion::TLSv1_2));

    let only13 = ServerTls::builder(identity(&leaf))
        .minimum_version(TlsVersion::Tls13)
        .build()
        .unwrap();
    let server13 = serve(&only13);
    let client12 = Tls::builder()
        .trust(Trust::Roots(vec![ca.der()]))
        .client_certificates(ClientCertificates::None)
        .maximum_version(TlsVersion::Tls12)
        .build()
        .unwrap();
    assert!(
        https_get(
            client12.client_config("localhost").unwrap(),
            server13.addr,
            "localhost"
        )
        .is_err()
    );
    let inverted = ServerTls::builder(identity(&leaf))
        .minimum_version(TlsVersion::Tls13)
        .maximum_version(TlsVersion::Tls12)
        .build();
    assert!(matches!(inverted, Err(Error::Tls(_))));
}

/// A key that signs for its owner and counts the signatures: what a keystore-held key looks like
/// to the server, which only ever asks it to sign.
#[derive(Debug)]
struct HeldKey {
    inner: Arc<dyn SigningKey>,
    signatures: Arc<AtomicUsize>,
}

#[derive(Debug)]
struct HeldSigner {
    inner: Box<dyn Signer>,
    signatures: Arc<AtomicUsize>,
}

impl SigningKey for HeldKey {
    fn choose_scheme(&self, offered: &[SignatureScheme]) -> Option<Box<dyn Signer>> {
        Some(Box::new(HeldSigner {
            inner: self.inner.choose_scheme(offered)?,
            signatures: Arc::clone(&self.signatures),
        }))
    }

    fn algorithm(&self) -> rustls::SignatureAlgorithm {
        self.inner.algorithm()
    }
}

impl Signer for HeldSigner {
    fn sign(&self, message: &[u8]) -> Result<Vec<u8>, rustls::Error> {
        self.signatures.fetch_add(1, Ordering::SeqCst);
        self.inner.sign(message)
    }

    fn scheme(&self) -> SignatureScheme {
        self.inner.scheme()
    }
}

#[test]
fn a_server_key_held_elsewhere_signs_through_the_identity() {
    let ca = Ca::new("Server CA");
    let leaf = ca.issue_server("localhost");
    let signatures = Arc::new(AtomicUsize::new(0));
    let held = Arc::new(HeldKey {
        inner: rustls::crypto::ring::sign::any_supported_type(&leaf.key()).unwrap(),
        signatures: Arc::clone(&signatures),
    });
    let identity = Identity::new(leaf.chain.clone(), held, "held").unwrap();
    let server = serve(&ServerTls::builder(identity).build().unwrap());
    https_get(
        client(&ca, None).client_config("localhost").unwrap(),
        server.addr,
        "localhost",
    )
    .unwrap();
    assert_eq!(signatures.load(Ordering::SeqCst), 1);
}

#[test]
fn logging_session_secrets_is_reported_as_a_non_default() {
    let ca = Ca::new("Server CA");
    let leaf = identity(&ca.issue_server("localhost"));
    let directory = tempfile::tempdir().unwrap();
    let plain = ServerTls::builder(leaf.clone()).build().unwrap();
    assert!(plain.non_defaults().is_empty());
    let logging = ServerTls::builder(leaf)
        .key_log(KeyLogging::File(directory.path().join("server-keys.log")))
        .build()
        .unwrap();
    assert_eq!(logging.non_defaults()[0].setting, "key_log");
}

#[test]
fn client_auth_against_the_system_roots_is_a_listed_weakening() {
    let ca = Ca::new("Listed CA");
    let leaf = ca.issue_server("localhost");
    let make = |auth: ClientAuth| ServerTls::builder(identity(&leaf)).client_auth(auth);

    assert!(make(ClientAuth::None).non_defaults().is_empty());
    assert!(
        make(ClientAuth::Required(Trust::Roots(vec![ca.der()])))
            .non_defaults()
            .is_empty()
    );
    for auth in [
        ClientAuth::Required(Trust::System),
        ClientAuth::Optional(Trust::System),
    ] {
        let builder = make(auth);
        let listed = builder.non_defaults();
        assert_eq!(listed.len(), 1);
        assert_eq!(listed[0].setting, "client_auth");
        assert_eq!(listed[0].value, "system roots");
        assert_eq!(builder.build().unwrap().non_defaults(), listed);
    }
}
